const { chromium } = require('playwright');
const SRV = 'http://127.0.0.1:18611';
(async () => {
  const b = await chromium.launch();
  const pg = await b.newPage();
  await fetch(SRV + '/__log');                       // vacía el registro del servidor
  await pg.goto(SRV + '/documento.html');
  await pg.click('text=Villa Martelli');
  await pg.waitForLoadState();
  console.log('después del clic:', pg.url(), '|', await pg.title());
  console.log('el servidor vio:', JSON.parse(await (await fetch(SRV + '/__log')).text()).join(', '));
  await b.close();
})();

const raiz = document.getElementById('raiz');
let envios = [];
let filtro = '';
function dibujar() {
  const visibles = envios.filter(e => e.estado.includes(filtro));
  raiz.innerHTML = '<h1>Envíos del día</h1>' +
    '<input id="f" placeholder="Filtrar por estado" value="' + filtro + '">' +
    '<ul>' + visibles.map(e => '<li>' + e.id + ': ' + e.estado + '</li>').join('') + '</ul>';
  const f = document.getElementById('f');
  f.addEventListener('input', () => { filtro = f.value; dibujar(); f.focus(); });
}
fetch('/api/envios.json').then(r => r.json()).then(d => { envios = d; dibujar(); });
